-- Checkpoint 248 / V-05: append-only Sturz-/Ereignisanalyse mit überprüfbarer Versorgungsanpassung.
-- Lokaler additiver Entwurf; bewusst nicht gegen eine produktive Datenbank ausgeführt.
CREATE TABLE IF NOT EXISTS public.qm_fall_event_analyses(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE RESTRICT,
 source_safety_incident_id uuid NOT NULL REFERENCES public.qm_safety_incidents(id) ON DELETE RESTRICT,source_care_record_id uuid NOT NULL REFERENCES public.clinical_documentation_entries(id) ON DELETE RESTRICT,event_type text NOT NULL CHECK(event_type IN('fall','other_care_event')),
 event_summary text NOT NULL CHECK(length(btrim(event_summary))>=5),documented_consequences text NOT NULL CHECK(length(btrim(documented_consequences))>=3),occurred_at timestamptz NOT NULL,observed_at timestamptz NOT NULL CHECK(observed_at>=occurred_at),recorded_at timestamptz NOT NULL CHECK(recorded_at>=observed_at),
 recorded_by uuid NOT NULL REFERENCES auth.users(id),recorded_by_name text NOT NULL CHECK(btrim(recorded_by_name)<>''),request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),UNIQUE(tenant_id,client_request_id),UNIQUE(tenant_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_fall_event_analysis_events(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,analysis_id uuid NOT NULL REFERENCES public.qm_fall_event_analyses(id) ON DELETE RESTRICT,sequence_no integer NOT NULL CHECK(sequence_no>=1),
 event_kind text NOT NULL CHECK(event_kind IN('causal_analysis','care_adjustment','repeat_check','analysis_closure','reopened')),occurred_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL CHECK(recorded_at>=occurred_at),actor_id uuid NOT NULL REFERENCES auth.users(id),actor_name text NOT NULL CHECK(btrim(actor_name)<>''),summary text NOT NULL CHECK(length(btrim(summary))>=5),
 factor_codes text[] NOT NULL DEFAULT '{}',cause_certainty text CHECK(cause_certainty IN('confirmed','contributing','unclear')),uncertainty_note text,responsible_id uuid,responsible_name text,care_plan_id uuid,care_plan_version_id uuid,effective_at timestamptz,planned_review_due_at timestamptz,observed_from timestamptz,observed_until timestamptz,review_outcome text CHECK(review_outcome IN('effective','partially_effective','not_effective','insufficient_observation')),recurrence_observed boolean,result_sha256 text CHECK(result_sha256~'^[0-9a-f]{64}$'),references_event_ids uuid[] NOT NULL DEFAULT '{}',request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),
 UNIQUE(tenant_id,client_request_id),UNIQUE(analysis_id,sequence_no),UNIQUE(analysis_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_fall_event_analysis_evidence(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,analysis_id uuid NOT NULL REFERENCES public.qm_fall_event_analyses(id) ON DELETE RESTRICT,event_id uuid NOT NULL REFERENCES public.qm_fall_event_analysis_events(id) ON DELETE RESTRICT,position_no integer NOT NULL CHECK(position_no>=1),source_type text NOT NULL CHECK(source_type IN('safety_incident','care_record','care_plan_version','tour_stop_emergency','assessment','other')),source_entity_id uuid NOT NULL,source_version_id uuid,record_locator text NOT NULL CHECK(btrim(record_locator)<>''),source_sha256 text NOT NULL CHECK(source_sha256~'^[0-9a-f]{64}$'),UNIQUE(event_id,position_no),UNIQUE(event_id,id)
);
ALTER TABLE public.qm_fall_event_analyses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.qm_fall_event_analysis_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.qm_fall_event_analysis_evidence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.qm_fall_event_analyses,public.qm_fall_event_analysis_events,public.qm_fall_event_analysis_evidence FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.qm_fall_event_analyses,public.qm_fall_event_analysis_events,public.qm_fall_event_analysis_evidence TO authenticated;
DROP POLICY IF EXISTS qm_fall_event_analyses_read ON public.qm_fall_event_analyses;
CREATE POLICY qm_fall_event_analyses_read ON public.qm_fall_event_analyses FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_fall_event_analysis_events_read ON public.qm_fall_event_analysis_events;
CREATE POLICY qm_fall_event_analysis_events_read ON public.qm_fall_event_analysis_events FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_fall_event_analysis_evidence_read ON public.qm_fall_event_analysis_evidence;
CREATE POLICY qm_fall_event_analysis_evidence_read ON public.qm_fall_event_analysis_evidence FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
CREATE OR REPLACE FUNCTION care_private.protect_qm_fall_event_analysis_history()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN RAISE EXCEPTION 'Sturz- und Ereignisanalyse bleibt append-only.' USING ERRCODE='42501';END$$;
DROP TRIGGER IF EXISTS protect_qm_fall_event_analyses ON public.qm_fall_event_analyses;
CREATE TRIGGER protect_qm_fall_event_analyses BEFORE UPDATE OR DELETE ON public.qm_fall_event_analyses FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_fall_event_analysis_history();
DROP TRIGGER IF EXISTS protect_qm_fall_event_analysis_events ON public.qm_fall_event_analysis_events;
CREATE TRIGGER protect_qm_fall_event_analysis_events BEFORE UPDATE OR DELETE ON public.qm_fall_event_analysis_events FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_fall_event_analysis_history();
DROP TRIGGER IF EXISTS protect_qm_fall_event_analysis_evidence ON public.qm_fall_event_analysis_evidence;
CREATE TRIGGER protect_qm_fall_event_analysis_evidence BEFORE UPDATE OR DELETE ON public.qm_fall_event_analysis_evidence FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_fall_event_analysis_history();

CREATE OR REPLACE FUNCTION public.record_qm_fall_event_analysis(p_payload jsonb,p_client_request_id uuid)RETURNS public.qm_fall_event_analyses
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t uuid:=public.current_tenant_id();actor uuid:=auth.uid();actor_name text:=public.clinical_actor_name();actual_time timestamptz:=clock_timestamp();result public.qm_fall_event_analyses;prior public.qm_fall_event_analyses;root_fp text;event_item record;evidence_item record;event_fp text;seq integer;last_kind text;last_occurred_at timestamptz;last_recorded_at timestamptz;last_reopen integer:=0;cause_count integer;adjustment_count integer;check_count integer;refs uuid[];client uuid;safety uuid;care_record uuid;factor_values text[];effective_at timestamptz;observed_from timestamptz;observed_until timestamptz;
BEGIN
 IF t IS NULL OR actor IS NULL OR NOT public.has_permission('qm.create_measure')THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;
 IF p_payload IS NULL OR p_client_request_id IS NULL OR p_payload->>'clientRequestId' IS DISTINCT FROM p_client_request_id::text OR COALESCE(p_payload->>'analysisId','')='' OR jsonb_typeof(p_payload->'events')<>'array' OR COALESCE(p_payload->>'occurredAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' OR COALESCE(p_payload->>'observedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' OR COALESCE(p_payload->>'recordedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' THEN RAISE EXCEPTION 'Ereignisanalyse ist unvollständig.' USING ERRCODE='23514';END IF;
 client:=(p_payload->>'clientId')::uuid;safety:=(p_payload->>'sourceSafetyIncidentId')::uuid;care_record:=(p_payload->>'sourceCareRecordId')::uuid;
 IF(p_payload->>'tenantId')::uuid IS DISTINCT FROM t OR COALESCE(p_payload->>'eventType','')NOT IN('fall','other_care_event')OR NOT EXISTS(SELECT 1 FROM public.clients WHERE tenant_id=t AND id=client)THEN RAISE EXCEPTION 'Mandant, Pflegefall oder Ereignisart ist widersprüchlich.' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.qm_safety_incidents WHERE tenant_id=t AND id=safety AND client_id=client)THEN RAISE EXCEPTION 'Ausgangsereignis fehlt oder gehört nicht zum Pflegefall.' USING ERRCODE='23503';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.clinical_documentation_entries WHERE tenant_id=t AND id=care_record AND client_id=client AND signature_status<>'superseded')THEN RAISE EXCEPTION 'Originaler Pflegeverlauf fehlt oder gehört nicht zum Pflegefall.' USING ERRCODE='23503';END IF;
 root_fp:=md5(jsonb_build_object('root',p_payload-'events')::text);PERFORM pg_advisory_xact_lock(hashtext(t::text),hashtext(p_payload->>'analysisId'));
 SELECT*INTO prior FROM public.qm_fall_event_analyses WHERE tenant_id=t AND id=(p_payload->>'analysisId')::uuid;
 IF FOUND THEN IF prior.request_fingerprint IS DISTINCT FROM root_fp OR prior.client_request_id IS DISTINCT FROM p_client_request_id THEN RAISE EXCEPTION 'Analyseidentität wurde anders verwendet.' USING ERRCODE='40001';END IF;result:=prior;
 ELSE
  IF(p_payload->>'recordedBy')::uuid IS DISTINCT FROM actor OR btrim(p_payload->>'recordedByName')IS DISTINCT FROM btrim(actor_name)OR(p_payload->>'occurredAt')::timestamptz>(p_payload->>'observedAt')::timestamptz OR(p_payload->>'observedAt')::timestamptz>(p_payload->>'recordedAt')::timestamptz OR(p_payload->>'recordedAt')::timestamptz>actual_time THEN RAISE EXCEPTION 'Zeitfolge oder Erfassungsidentität ist widersprüchlich.' USING ERRCODE='23514';END IF;
  INSERT INTO public.qm_fall_event_analyses(id,client_request_id,tenant_id,client_id,source_safety_incident_id,source_care_record_id,event_type,event_summary,documented_consequences,occurred_at,observed_at,recorded_at,recorded_by,recorded_by_name,request_fingerprint)VALUES((p_payload->>'analysisId')::uuid,p_client_request_id,t,client,safety,care_record,p_payload->>'eventType',btrim(p_payload->>'eventSummary'),btrim(p_payload->>'documentedConsequences'),(p_payload->>'occurredAt')::timestamptz,(p_payload->>'observedAt')::timestamptz,(p_payload->>'recordedAt')::timestamptz,actor,actor_name,root_fp)RETURNING*INTO result;
 END IF;
 SELECT COALESCE(max(sequence_no),0),(array_agg(occurred_at ORDER BY sequence_no DESC))[1],(array_agg(recorded_at ORDER BY sequence_no DESC))[1],(array_agg(event_kind ORDER BY sequence_no DESC))[1]INTO seq,last_occurred_at,last_recorded_at,last_kind FROM public.qm_fall_event_analysis_events WHERE analysis_id=result.id;SELECT COALESCE(max(sequence_no),0)INTO last_reopen FROM public.qm_fall_event_analysis_events WHERE analysis_id=result.id AND event_kind='reopened';
 FOR event_item IN SELECT value,ordinality FROM jsonb_array_elements(p_payload->'events')WITH ORDINALITY LOOP
  event_fp:=md5(event_item.value::text);IF EXISTS(SELECT 1 FROM public.qm_fall_event_analysis_events WHERE tenant_id=t AND client_request_id=(event_item.value->>'clientRequestId')::uuid AND request_fingerprint=event_fp)THEN CONTINUE;END IF;
  IF EXISTS(SELECT 1 FROM public.qm_fall_event_analysis_events WHERE tenant_id=t AND client_request_id=(event_item.value->>'clientRequestId')::uuid)OR jsonb_typeof(event_item.value->'evidence')<>'array'OR jsonb_typeof(event_item.value->'referencesEventIds')<>'array'OR COALESCE(event_item.value->>'occurredAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$'OR COALESCE(event_item.value->>'recordedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$'OR(event_item.value->>'occurredAt')::timestamptz>(event_item.value->>'recordedAt')::timestamptz OR(event_item.value->>'recordedAt')::timestamptz>actual_time OR(last_occurred_at IS NOT NULL AND(event_item.value->>'occurredAt')::timestamptz<last_occurred_at)OR(last_recorded_at IS NOT NULL AND(event_item.value->>'recordedAt')::timestamptz<last_recorded_at)THEN RAISE EXCEPTION 'Verlauf ist doppelt, unvollständig oder zeitlich widersprüchlich.' USING ERRCODE='40001';END IF;
  refs:=ARRAY(SELECT jsonb_array_elements_text(event_item.value->'referencesEventIds')::uuid);factor_values:=ARRAY(SELECT jsonb_array_elements_text(COALESCE(event_item.value->'factorCodes','[]'::jsonb)));cause_count:=(SELECT count(*)FROM public.qm_fall_event_analysis_events WHERE analysis_id=result.id AND sequence_no>last_reopen AND event_kind='causal_analysis');adjustment_count:=(SELECT count(*)FROM public.qm_fall_event_analysis_events WHERE analysis_id=result.id AND sequence_no>last_reopen AND event_kind='care_adjustment');check_count:=(SELECT count(*)FROM public.qm_fall_event_analysis_events WHERE analysis_id=result.id AND sequence_no>last_reopen AND event_kind='repeat_check');
  IF last_kind='analysis_closure'AND event_item.value->>'kind'<>'reopened'THEN RAISE EXCEPTION 'Geschlossene Analyse benötigt Wiederaufnahme.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'IN('causal_analysis','care_adjustment','repeat_check','analysis_closure')AND jsonb_array_length(event_item.value->'evidence')<1 THEN RAISE EXCEPTION 'Analyseschritt benötigt einen konkreten Originalbeleg.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='causal_analysis'AND(cardinality(factor_values)<1 OR factor_values<@ARRAY['intrinsic','medication','environment','assistive_device','care_process','unknown']::text[]IS FALSE OR COALESCE(event_item.value->>'causeCertainty','')NOT IN('confirmed','contributing','unclear')OR(event_item.value->>'causeCertainty'='unclear'AND btrim(COALESCE(event_item.value->>'uncertaintyNote',''))=''))THEN RAISE EXCEPTION 'Ursachenanalyse benötigt Faktoren, Sicherheit und Beleg.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='care_adjustment'THEN effective_at:=(event_item.value->>'effectiveAt')::timestamptz;IF btrim(COALESCE(event_item.value->>'responsibleName',''))=''OR NULLIF(event_item.value->>'carePlanId','')IS NULL OR NULLIF(event_item.value->>'carePlanVersionId','')IS NULL OR effective_at<(event_item.value->>'occurredAt')::timestamptz OR(event_item.value->>'plannedReviewDueAt')::timestamptz<=effective_at OR NOT EXISTS(SELECT 1 FROM public.qm_fall_event_analysis_events WHERE analysis_id=result.id AND sequence_no>last_reopen AND event_kind='causal_analysis'AND id=ANY(refs))OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(event_item.value->'evidence')e WHERE e->>'sourceType'='care_plan_version'AND e->>'sourceEntityId'=event_item.value->>'carePlanId'AND e->>'sourceVersionId'=event_item.value->>'carePlanVersionId')THEN RAISE EXCEPTION 'Versorgungsanpassung benötigt Ursache, Verantwortung, Pflegeplanfassung und Prüftermin.' USING ERRCODE='23514';END IF;END IF;
  IF event_item.value->>'kind'='repeat_check'THEN observed_from:=(event_item.value->>'observedFrom')::timestamptz;observed_until:=(event_item.value->>'observedUntil')::timestamptz;SELECT e.effective_at INTO effective_at FROM public.qm_fall_event_analysis_events e WHERE e.analysis_id=result.id AND e.sequence_no>last_reopen AND e.event_kind='care_adjustment'AND e.id=ANY(refs)ORDER BY e.sequence_no DESC LIMIT 1;IF effective_at IS NULL OR observed_from<effective_at OR observed_from>observed_until OR observed_until>(event_item.value->>'occurredAt')::timestamptz OR COALESCE(event_item.value->>'reviewOutcome','')NOT IN('effective','partially_effective','not_effective','insufficient_observation')OR jsonb_typeof(event_item.value->'recurrenceObserved')<>'boolean'OR COALESCE(event_item.value->>'resultSha256','')!~'^[0-9a-f]{64}$'OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(event_item.value->'evidence')e WHERE e->>'sourceType'='care_record')THEN RAISE EXCEPTION 'Wiederholungsprüfung benötigt Anpassung, Zeitraum, Ergebnis und Pflegeverlaufsbeleg.' USING ERRCODE='23514';END IF;END IF;
  IF event_item.value->>'kind'='analysis_closure'AND(NOT public.has_permission('qm.close_measure')OR cause_count<1 OR adjustment_count<1 OR check_count<1 OR COALESCE(event_item.value->>'resultSha256','')!~'^[0-9a-f]{64}$'OR NOT EXISTS(SELECT 1 FROM public.qm_fall_event_analysis_events WHERE analysis_id=result.id AND sequence_no>last_reopen AND event_kind='causal_analysis'AND id=ANY(refs))OR NOT EXISTS(SELECT 1 FROM public.qm_fall_event_analysis_events WHERE analysis_id=result.id AND sequence_no>last_reopen AND event_kind='care_adjustment'AND id=ANY(refs))OR NOT EXISTS(SELECT 1 FROM public.qm_fall_event_analysis_events WHERE analysis_id=result.id AND sequence_no>last_reopen AND event_kind='repeat_check'AND id=ANY(refs)))THEN RAISE EXCEPTION 'Analyseabschluss benötigt Ursache, Anpassung, Wiederholungsprüfung und Schließrecht.' USING ERRCODE='42501';END IF;
  IF event_item.value->>'kind'='reopened'AND(last_kind<>'analysis_closure'OR jsonb_array_length(event_item.value->'evidence')<>0)THEN RAISE EXCEPTION 'Nur eine abgeschlossene Analyse kann ohne erfundenen Beleg wiederaufgenommen werden.' USING ERRCODE='23514';END IF;
  seq:=seq+1;INSERT INTO public.qm_fall_event_analysis_events(id,client_request_id,tenant_id,analysis_id,sequence_no,event_kind,occurred_at,recorded_at,actor_id,actor_name,summary,factor_codes,cause_certainty,uncertainty_note,responsible_id,responsible_name,care_plan_id,care_plan_version_id,effective_at,planned_review_due_at,observed_from,observed_until,review_outcome,recurrence_observed,result_sha256,references_event_ids,request_fingerprint)VALUES((event_item.value->>'eventId')::uuid,(event_item.value->>'clientRequestId')::uuid,t,result.id,seq,event_item.value->>'kind',(event_item.value->>'occurredAt')::timestamptz,(event_item.value->>'recordedAt')::timestamptz,actor,actor_name,btrim(event_item.value->>'summary'),factor_values,NULLIF(event_item.value->>'causeCertainty',''),NULLIF(btrim(COALESCE(event_item.value->>'uncertaintyNote','')),''),NULLIF(event_item.value->>'responsibleId','')::uuid,NULLIF(btrim(COALESCE(event_item.value->>'responsibleName','')),''),NULLIF(event_item.value->>'carePlanId','')::uuid,NULLIF(event_item.value->>'carePlanVersionId','')::uuid,NULLIF(event_item.value->>'effectiveAt','')::timestamptz,NULLIF(event_item.value->>'plannedReviewDueAt','')::timestamptz,NULLIF(event_item.value->>'observedFrom','')::timestamptz,NULLIF(event_item.value->>'observedUntil','')::timestamptz,NULLIF(event_item.value->>'reviewOutcome',''),NULLIF(event_item.value->>'recurrenceObserved','')::boolean,NULLIF(event_item.value->>'resultSha256',''),refs,event_fp);
  FOR evidence_item IN SELECT value,ordinality FROM jsonb_array_elements(event_item.value->'evidence')WITH ORDINALITY LOOP IF COALESCE(evidence_item.value->>'sourceType','')NOT IN('safety_incident','care_record','care_plan_version','tour_stop_emergency','assessment','other')OR btrim(COALESCE(evidence_item.value->>'recordLocator',''))=''OR COALESCE(evidence_item.value->>'sourceSha256','')!~'^[0-9a-f]{64}$'THEN RAISE EXCEPTION 'Beleg ist unvollständig.' USING ERRCODE='23514';END IF;INSERT INTO public.qm_fall_event_analysis_evidence(id,tenant_id,analysis_id,event_id,position_no,source_type,source_entity_id,source_version_id,record_locator,source_sha256)VALUES((evidence_item.value->>'evidenceId')::uuid,t,result.id,(event_item.value->>'eventId')::uuid,evidence_item.ordinality,evidence_item.value->>'sourceType',(evidence_item.value->>'sourceEntityId')::uuid,NULLIF(evidence_item.value->>'sourceVersionId','')::uuid,btrim(evidence_item.value->>'recordLocator'),evidence_item.value->>'sourceSha256');END LOOP;
  last_kind:=event_item.value->>'kind';last_occurred_at:=(event_item.value->>'occurredAt')::timestamptz;last_recorded_at:=(event_item.value->>'recordedAt')::timestamptz;IF last_kind='reopened'THEN last_reopen:=seq;END IF;
 END LOOP;
 INSERT INTO public.care_audit_events(tenant_id,client_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name)VALUES(t,client,'qm_fall_event_analysis',result.id,'fall_event_analysis_recorded','Ereignisanalyse append-only fortgeschrieben; Plantermin, tatsächliche Prüfung und Versorgungshistorie bleiben getrennt.',to_jsonb(result),actor,actor_name);RETURN result;
END$$;
REVOKE ALL ON FUNCTION public.record_qm_fall_event_analysis(jsonb,uuid)FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.record_qm_fall_event_analysis(jsonb,uuid)TO authenticated;
